export function getGroupForCategory(catId) {
  if (typeof EBAY_CATEGORIES !== 'undefined' && EBAY_CATEGORIES[catId]) {
    return EBAY_CATEGORIES[catId].group || 'default';
  }
  return CATEGORY_GROUP_MAP[catId] || 'default';
}

export function getCategoryName(catId) {
  if (typeof EBAY_CATEGORIES !== 'undefined' && EBAY_CATEGORIES[catId]) {
    return EBAY_CATEGORIES[catId].name || null;
  }
  if (typeof ebayCategoryMap !== 'undefined' && ebayCategoryMap[catId]) {
    return ebayCategoryMap[catId][0] || null;
  }
  return null;
}

